script:
html { scroll-behavior: smooth; }
::selection { background: #D8FF3D; color: #131308; }

html.tm-js .tm-rise { opacity: 0; transform: translateY(24px); }
html.tm-js .tm-rise.tm-in {
  opacity: 1; transform: none;
  transition: opacity 0.8s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}
html.tm-js .tm-d1.tm-in { transition-delay: 0.12s; }
html.tm-js .tm-d2.tm-in { transition-delay: 0.24s; }

.tm-grow { flex-grow: 1; flex-shrink: 1; min-width: 0; }

.tm-ul {
  background-image: linear-gradient(#D8FF3D, #D8FF3D);
  background-position: left bottom; background-repeat: no-repeat;
  background-size: 0% 2px;
  transition: background-size 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}
.tm-ul:hover { background-size: 100% 2px; }

.tm-btn { transition: transform 0.22s ease, box-shadow 0.22s ease; }
.tm-btn:hover { transform: translate(-2px, -2px);
  box-shadow: 4px 4px 0 #F4F4F0; }
.tm-btn-o { transition: background-color 0.25s ease, color 0.25s ease,
  border-color 0.25s ease; }
.tm-btn-o:hover { background-color: #F4F4F0; border-color: #F4F4F0;
  color: #131308; }
.tm-btn-d { transition: transform 0.22s ease, box-shadow 0.22s ease; }
.tm-btn-d:hover { transform: translate(-2px, -2px);
  box-shadow: 4px 4px 0 #131308; }

.tm-card { transition: transform 0.35s cubic-bezier(0.22, 1, 0.36, 1); }
.tm-card:hover { transform: translateY(-5px); }
.tm-card img { transition: transform 0.6s cubic-bezier(0.22, 1, 0.36, 1); }
.tm-card:hover img { transform: scale(1.03); }

.tm-pillar { transition: border-color 0.35s ease; }
.tm-pillar:hover { border-color: #D8FF3D; }

.tm-cell { transition: background-color 0.25s ease; }
.tm-cell:hover { background-color: #1B1B18; }

@keyframes tm-scroll {
  from { transform: translateX(0); }
  to { transform: translateX(-33.333%); }
}
html.tm-js .tm-ticker { animation: tm-scroll 22s linear infinite; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  html.tm-js .tm-ticker { animation: none; }
}
